private int pop(){
    if (stack == null) {
        throw new IllegalStateException("Stack not initialized");
    }
    if (stackCount == 0) {
        throw new IllegalStateException("Stack underflow: cannot pop from empty stack");
    }
    int value = stack[--stackCount];
    // Optional: clear the slot to avoid memory leaks
    stack[stackCount] = 0;
    return value;
}

