public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long value : array) {
        int elementHash = (int)(value ^ (value >>> 32));
        result = 31 * result + elementHash;
    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) return null;
    TreeNode<T> left = node.left;
    if (left == null) return node; // cannot rotate
    // detach left's right subtree
    node.left = left.right;
    if (node.left != null) node.left.parent = node;
    // make node the right child of left
    left.right = node;
    // update parents
    left.parent = node.parent;
    node.parent = left;
    // update grandparent's child reference if exists
    if (left.parent != null) {
        if (left.parent.left == node) {
            left.parent.left = left;
        } else if (left.parent.right == node) {
            left.parent.right = left;
        }
    }
    return left;
}

