public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream is null");
    }
    if (message == null) {
        throw new NullPointerException("Message is null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }
    if (buffer == null) {
        throw new NullPointerException("LinkedBuffer is null");
    }
    // Compute the serialized size of the message
    int size = schema.getSerializedSize(message);
    // Encode the message into the buffer
    schema.writeTo(buffer, message);
    // Retrieve the underlying byte array and its used length
    byte[] buf = buffer.getBuffer();
    int bufSize = buffer.getSize();
    // Write the length prefix as a varint32
    int tempSize = size;
    while ((tempSize & ~0x7F) != 0) {
        out.write((tempSize & 0x7F) | 0x80);
        tempSize >>>= 7;
    }
    out.write(tempSize);
    // Write the actual message bytes
    out.write(buf, 0, bufSize);
    // Return the size of the message (excluding the length prefix)
    return bufSize;
}

