public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Map<TypeVariable<?>, Type> typeVarMap = buildTypeVariableMap(targetType);
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type arg = args[i];
        // Resolve type variables
        arg = resolveTypeVariable(arg, typeVarMap);
        if (arg instanceof TypeVariable) {
            return null; // unresolved
        }
        Class<?> cls = null;
        if (arg instanceof Class) {
            cls = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) arg).getRawType();
            if (raw instanceof Class) {
                cls = (Class<?>) raw;
            }
        } else if (arg instanceof GenericArrayType) {
            Type comp = ((GenericArrayType) arg).getGenericComponentType();
            comp = resolveTypeVariable(comp, typeVarMap);
            if (comp instanceof Class) {
                cls = Array.newInstance((Class<?>) comp, 0).getClass();
            } else if (comp instanceof ParameterizedType) {
                Type raw = ((ParameterizedType) comp).getRawType();
                if (raw instanceof Class) {
                    cls = Array.newInstance((Class<?>) raw, 0).getClass();
                }
            }
        }
        if (cls == null) {
            return null;
        }
        result[i] = cls;
    }
    return result;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> clazz) {
    Map<TypeVariable<?>, Type> map = new HashMap<>();
    // Traverse class hierarchy
    Class<?> current = clazz;
    while (current != null) {
        Type genericSuper = current.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) genericSuper;
            TypeVariable<?>[] vars = current.getTypeParameters();
            Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
        }
        // Interfaces
        for (Type iface : current.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType pt = (ParameterizedType) iface;
                Class<?> ifaceClass = (Class<?>) pt.getRawType();
                TypeVariable<?>[] vars = ifaceClass.getTypeParameters();
                Type[] args = pt.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    map.put(vars[i], args[i]);
                }
            }
        }
        current = current.getSuperclass();
    }
    return map;
}

