public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        // Retrieve the current mapping for the given table (index)
        Mappings current = getCurrentMapping(tableName);
        if (current == null) {
            // If no current mapping exists, return the input mappings as is
            return mappings;
        }

        // Prepare a new Mappings object to hold the differences
        Mappings diff = new Mappings();

        // Iterate over the fields in the input mappings
        Map<String, Object> inputSource = mappings.getSource();
        Map<String, Object> currentSource = current.getSource();

        if (inputSource != null) {
            for (Map.Entry<String, Object> entry : inputSource.entrySet()) {
                String field = entry.getKey();

                // Skip the _source configuration to avoid update conflicts
                if ("_source".equals(field)) {
                    continue;
                }

                // If the field does not exist in the current mapping, add it to diff
                if (currentSource == null || !currentSource.containsKey(field)) {
                    diff.put(field, entry.getValue());
                }
            }
        }

        return diff;
    } catch (Exception e) {
        // In case of any error, return an empty Mappings instance
        return new Mappings();
    }
}

