}

public boolean equals(final byte[] data, int offset, final int len) {
    // Validate input array
    if (data == null) {
        return false;
    }
    // Validate offset and length bounds
    if (offset < 0 || len < 0 || offset > data.length - len) {
        return false;
    }
    // Internal array reference (assumed to be a field named 'data')
    byte[] internal = this.data;
    if (internal == null) {
        return false;
    }
    // Lengths must match for a full equality check
    if (internal.length != len) {
        return false;
    }
    // Compare element by element
    for (int i = 0; i < len; i++) {
        if (internal[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

