public void removeFromTreeEdgeList() {
    // Remove from the first doubly linked list
    if (prev != null) {
        prev.next = next;
    }
    if (next != null) {
        next.prev = prev;
    }
    prev = next = null;

    // Remove from the second doubly linked list
    if (prevTreeEdge != null) {
        prevTreeEdge.nextTreeEdge = nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = prevTreeEdge;
    }
    prevTreeEdge = nextTreeEdge = null;
}

public static String findAndSubst(String key, java.util.Properties props) {
    if (props == null || key == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String var = matcher.group(1);
        String replacement = props.getProperty(var);
        if (replacement == null) {
            replacement = "";
        }
        replacement = java.util.regex.Matcher.quoteReplacement(replacement);
        matcher.appendReplacement(sb, replacement);
    }
    matcher.appendTail(sb);
    return sb.toString();
}

