    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffLen = suffix.length();
    if (suffLen > strLen) {
        return false;
    }
    if (suffLen == 0) {
        return true;
    }
    return str.regionMatches(ignoreCase, strLen - suffLen, suffix, 0, suffLen);
}

