    double maxX = box.getMaxX();
    if (maxX < minX) {
        throw new IllegalArgumentException("box maxX must be >= minX");
    }
    double midX = (minX + maxX) / 2.0;
    Box2D left = new Box2D(minX, box.getMinY(), midX, box.getMaxY());
