public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        i++;
        if (i >= len) {
            sb.append('\\');
            break;
        }
        char next = str.charAt(i);
        switch (next) {
            case 'n':
                sb.append('\n');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'r':
                sb.append('\r');
                break;
            case 'b':
                sb.append('\b');
                break;
            case 'f':
                sb.append('\f');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                // Unicode escape: \uXXXX
                int unicode = 0;
                int unicodeDigits = 0;
                while (unicodeDigits < 4 && i + 1 < len) {
                    char hexChar = str.charAt(i + 1);
                    if (Character.digit(hexChar, 16) != -1) {
                        unicode = (unicode << 4) + Character.digit(hexChar, 16);
                        i++;
                        unicodeDigits++;
                    } else {
                        break;
                    }
                }
                sb.append((char) unicode);
                break;
            default:
                if (next >= '0' && next <= '7') {
                    // Octal escape: up to three octal digits
                    int octal = next - '0';
                    int octalDigits = 1;
                    while (octalDigits < 3 && i + 1 < len) {
                        char octChar = str.charAt(i + 1);
                        if (octChar >= '0' && octChar <= '7') {
                            octal = (octal << 3) + (octChar - '0');
                            i++;
                            octalDigits++;
                        } else {
                            break;
                        }
                    }
                    sb.append((char) octal);
                } else {
                    // Unrecognized escape, keep as is
                    sb.append(next);
                }
                break;
        }
    }
    return sb.toString();
}

