final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Locate the offset of the CONSTANT_Utf8 entry in the class file buffer.
    int offset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    // The first two bytes after the tag give the length of the UTF-8 string.
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small for UTF-8 entry");
    }
    int pos = offset + 2; // start of the UTF-8 bytes
    int end = pos + length;
    int charPos = 0;
    while (pos < end) {
        int b = classFileBuffer[pos++] & 0xFF;
        if ((b & 0x80) == 0) {
            // one-byte sequence
            charBuffer[charPos++] = (char) b;
        } else if ((b & 0xE0) == 0xC0) {
            // two-byte sequence
            int b2 = classFileBuffer[pos++] & 0xFF;
            charBuffer[charPos++] = (char) (((b & 0x1F) << 6) | (b2 & 0x3F));
        } else {
            // three-byte sequence
            int b2 = classFileBuffer[pos++] & 0xFF;
            int b3 = classFileBuffer[pos++] & 0xFF;
            charBuffer[charPos++] = (char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
        }
    }
    return new String(charBuffer, 0, charPos);
}

