    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Iterate until we find a node that satisfies the predicate or reach the stop node.
    while (true) {
        Node current = circ.getNode();
        try {
            if (predicate.test(current)) {
                return circ;
            }
        } catch (Exception e) {
            throw new IllegalArgumentException("Predicate evaluation failed", e);
        }
        if (current.equals(stop)) {
            return circ;
        }
        circ.next();
    }
}

