private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            // trailing backslash, keep as is
            sb.append(c);
            break;
        }
        char next = input.charAt(i + 1);
        i++; // consume next
        try {
            if (next == 'u' || next == 'U') {
                // Unicode escape \uXXXX
                if (i + 4 >= len) {
                    // not enough digits, treat literally
                    sb.append('\\').append(next);
                    continue;
                }
                String hex = input.substring(i + 1, i + 5);
                int code = Integer.parseInt(hex, 16);
                sb.append((char) code);
                i += 4;
            } else if (next == 'x' || next == 'X') {
                // Hex escape \xNN
                if (i + 2 >= len) {
                    sb.append('\\').append(next);
                    continue;
                }
                String hex = input.substring(i + 1, i + 3);
                int code = Integer.parseInt(hex, 16);
                sb.append((char) code);
                i += 2;
            } else if (next >= '0' && next <= '7') {
                // Octal escape \NNN (up to 3 digits)
                int j = i;
                int count = 1;
                while (count < 3 && j + 1 < len && input.charAt(j + 1) >= '0' && input.charAt(j + 1) <= '7') {
                    j++;
                    count++;
                }
                String oct = input.substring(i, j + 1);
                int code = Integer.parseInt(oct, 8);
                sb.append((char) code);
                i = j;
            } else {
                // Simple escape: keep the escaped character
                sb.append(next);
            }
        } catch (NumberFormatException e) {
            // Invalid escape, keep as literal
            sb.append('\\').append(next);
        }
    }
    return sb.toString();
}

