private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffix.add(0, (int) sum);
    }
    return new Pair<>(suffix, sum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        return;
    }
    int n = arr.length;
    if (from < 0) {
        from = 0;
    }
    if (to >= n) {
        to = n - 1;
    }
    if (from >= to) {
        return;
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    // Move nodes one by one from the source list to this list.
    // This approach mimics removing each node from the source and adding it to the destination.
    while (list.size() > 0) {
        // Retrieve the first node of the source list.
        DoublyLinkedList.ListNodeImpl<E> node = list.getFirstNode();
        if (node == null) {
            // If for some reason the list reports a non‑zero size but has no nodes,
            // break to avoid an infinite loop.
            break;
        }
        // Remove the node from the source list.
        list.removeListNode(node);
        // Add the node to this list.
        this.addListNode(node);
    }
}

