public static Type resolveBound(TypeVariable<?> typeVariable){
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds != null && bounds.length > 0) {
            return bounds[0];
        }
    } catch (Exception e) {
        // ignore and fall through to return Unknown
    }
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    // A graph with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    TreeSet<Integer> set = new TreeSet<>();
    for (K k : keys){
        if (k == null){
            result.add(Integer.MIN_VALUE);
            continue;
        }
        if (!(k instanceof Integer)){
            throw new IllegalArgumentException("Key type must be Integer");
        }
        set.add((Integer) k);
    }
    for (K k : keys){
        if (k == null){
            result.add(Integer.MIN_VALUE);
            continue;
        }
        Integer val = (Integer) k;
        Integer lower = set.lower(val);
        result.add(lower != null ? lower : Integer.MIN_VALUE);
    }
    return result;
}

private void pop(final String descriptor){
    if (descriptor == null){
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int i = 0;
    if (descriptor.charAt(0) == '('){
        i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')'){
            // consume one type
            char c = descriptor.charAt(i);
            if (c == '['){
                // skip all '['
                while (i < descriptor.length() && descriptor.charAt(i) == '['){
                    i++;
                }
                if (i >= descriptor.length()){
                    throw new IllegalArgumentException("Invalid descriptor");
                }
                c = descriptor.charAt(i);
            }
            if (c == 'L'){
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1){
                    throw new IllegalArgumentException("Invalid descriptor");
                }
                i = semicolon + 1;
            } else {
                // primitive or void
                i++;
            }
            // pop one type from stack
            if (pos <= 0){
                throw new IllegalStateException("Stack underflow");
            }
            pos--;
        }
        // skip ')'
        i++;
        // return type is not popped
    } else {
        // single type descriptor
        char c = descriptor.charAt(i);
        if (c == '['){
            while (i < descriptor.length() && descriptor.charAt(i) == '['){
                i++;
            }
            if (i >= descriptor.length()){
                throw new IllegalArgumentException("Invalid descriptor");
            }
            c = descriptor.charAt(i);
        }
        if (c == 'L'){
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1){
                throw new IllegalArgumentException("Invalid descriptor");
            }
            i = semicolon + 1;
        } else {
            i++;
        }
        if (pos <= 0){
            throw new IllegalStateException("Stack underflow");
        }
        pos--;
    }
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("key cannot be null");
        }
        bounds.add(key.hashCode());
    }
    return bounds;
}

public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    // Percent-encode '{' and '}' characters
    return s.replace("{", "%7B").replace("}", "%7D");
}

public static boolean equals(Point2D p1, Point2D p2) {
    if (p1 == p2) return true;
    if (p1 == null || p2 == null) return false;
    double tolerance = 1e-9;
    return Math.abs(p1.getX() - p2.getX()) <= tolerance &&
           Math.abs(p1.getY() - p2.getY()) <= tolerance;
}

