public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str==null || substring==null) return false;
    int strLen = str.length();
    int subLen = substring.length();
    if(index<0 || index>strLen) return false;
    if(subLen==0) return true;
    if(index + subLen > strLen) return false;
    for(int i=0;i<subLen;i++){
        if(str.charAt(index+i)!=substring.charAt(i)) return false;
    }
    return true;
}

void function (LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getRenderedMessage();
    if (message == null) {
        return;
    }
    for (Session session : userSessions) {
        if (session == null) {
            continue;
        }
        try {
            session.getAsyncRemote().sendText(message);
        } catch (Exception e) {
            // ignore or log the exception
        }
    }
}

