private String buildContentRange(){
    try {
        if (start == null || end == null) {
            return null;
        }
        if (start < 0 || end < start) {
            throw new IllegalArgumentException("Invalid content range values");
        }
        StringBuilder sb = new StringBuilder();
        sb.append("bytes ").append(start).append("-").append(end).append("/");
        sb.append(total != null && total >= 0 ? total : "*");
        return sb.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to build Content-Range header", e);
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Attempt to parse each line into a ThreadSnapshot.
            // The actual parsing logic depends on the file format.
            // Here we assume a static factory method `ThreadSnapshot.parseFromLine(String)` exists.
            ThreadSnapshot snapshot = ThreadSnapshot.parseFromLine(line);
            if (snapshot != null) {
                allSnapshots.add(snapshot);
            }
        }
    }
    // If no time ranges specified, return all snapshots.
    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }
    List<ThreadSnapshot> filtered = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        long ts = snapshot.getTimestamp(); // assume this method exists
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (ts >= range.getStart() && ts <= range.getEnd()) {
                filtered.add(snapshot);
                break;
            }
        }
    }
    return filtered;
}
